func TestGettersSearchGetResponse(t *testing.T) {
	t.Run("GetSearchResponseDto", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &SearchGetResponse{}
		var expected *SearchResponseDto
		obj.SearchResponseDto = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetSearchResponseDto(), "getter should return the property value")
	})

	t.Run("GetSearchResponseDto_NilValue", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &SearchGetResponse{}
		obj.SearchResponseDto = nil

		// Act & Assert
		assert.Nil(t, obj.GetSearchResponseDto(), "getter should return nil when property is nil")
	})

	t.Run("GetSearchResponseDto_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *SearchGetResponse
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetSearchResponseDto() // Should return zero value
	})

	t.Run("GetClusteredSearchResponseDto", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &SearchGetResponse{}
		var expected *ClusteredSearchResponseDto
		obj.ClusteredSearchResponseDto = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetClusteredSearchResponseDto(), "getter should return the property value")
	})

	t.Run("GetClusteredSearchResponseDto_NilValue", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &SearchGetResponse{}
		obj.ClusteredSearchResponseDto = nil

		// Act & Assert
		assert.Nil(t, obj.GetClusteredSearchResponseDto(), "getter should return nil when property is nil")
	})

	t.Run("GetClusteredSearchResponseDto_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *SearchGetResponse
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetClusteredSearchResponseDto() // Should return zero value
	})

}

